const stop=new Set('a an and are as at be by can company for from has have in into is it job of on or our role that the their this to we will with you your team work working experience ability skills responsibilities requirements preferred required years year about all'.split(' '));
export function keywords(text){return [...new Set((text.toLowerCase().match(/[a-z][a-z0-9+#.-]*/g)||[]).map(w=>w.replace(/[.-]+$/,'')).filter(w=>w.length>2&&!stop.has(w)))];}
export function analyze(resume,jd){const terms=keywords(jd);const words=new Set(keywords(resume));const matched=terms.filter(t=>words.has(t));const missing=terms.filter(t=>!words.has(t));return {score:terms.length?Math.round(matched.length/terms.length*100):0,matched,missing,total:terms.length};}
export function rankedLines(resume,jd){const terms=new Set(keywords(jd));return resume.split('\n').map((text,index)=>({text,index,relevance:keywords(text).filter(t=>terms.has(t)).length})).filter(l=>l.text.trim()).sort((a,b)=>b.relevance-a.relevance||a.index-b.index);}
